const response = $input.first().json;
const now = new Date();
const monthStr = now.toISOString().slice(0, 7);
const dateStr = now.toISOString().slice(0, 10);

let alertTriggered = false;
let alertReason = '';
let markdown = '';

const execution = response.execution || {};
const result = execution.result || response.result || {};

if (response.error || execution.status === 'failed' || !result.ok) {
  markdown = `---\ntitle: Relatório Financeiro - ${monthStr}\nsource: usami-automation\nkind: finance-report\ncreated_at: ${now.toISOString()}\nstatus: unavailable\n---\n\n# 💳 Relatório Financeiro — ${monthStr}\n\n> ℹ️ *Acesso ao Open Finance não configurado ou temporariamente indisponível no momento da execução.*\n\nPara ativar, configure as credenciais da Pluggy ou Belvo no seu \`.env\` da Usami.\n`;
} else {
  const transactions = Array.isArray(result.transactions) ? result.transactions : [];
  const summary = result.summary || {};
  const totalSpent = summary.totalOutflow ?? 0;
  const totalInflow = summary.totalInflow ?? 0;

  let rows = '';
  for (const t of transactions) {
    const amount = Number(t.amount || 0);
    if (amount < -500) {
      alertTriggered = true;
      alertReason = `gasto de R$ ${Math.abs(amount).toFixed(2)} em ${t.description || 'estabelecimento'}`;
    }
    const signal = amount < 0 ? '-' : '+';
    rows += `| ${t.date || dateStr} | ${t.description || 'Transação'} | ${t.category || 'Geral'} | R$ ${Math.abs(amount).toFixed(2)} (${signal}) |\n`;
  }

  if (!rows) rows = '| - | Nenhuma transação recente registrada | - | - |\n';

  markdown = `---\ntitle: Relatório Financeiro - ${monthStr}\nsource: usami-automation\nkind: finance-report\ncreated_at: ${now.toISOString()}\nupdated_at: ${now.toISOString()}\n---\n\n# 💳 Relatório Financeiro — ${monthStr}\n\n### 📊 Resumo do Período\n- **Entradas Recentes:** R$ ${Number(totalInflow).toFixed(2)}\n- **Saídas Recentes:** R$ ${Math.abs(Number(totalSpent)).toFixed(2)}\n- **Última Atualização:** ${dateStr}\n\n### 🧾 Extrato Recente\n| Data | Descrição | Categoria | Valor |\n| :--- | :--- | :--- | :--- |\n${rows}\n\n### 💬 Observação da Usami\n> *"De olho nos números pra você não se apertar no fim do mês!"*\n`;
}

const proactiveSay = alertTriggered
  ? `Atenção! Identifiquei um ${alertReason}. Já anotei no seu relatório financeiro do Obsidian!`
  : `Atualizei seu relatório financeiro de ${monthStr} no Obsidian com o extrato recente.`;

const gesture = alertTriggered ? 'surprised' : 'nod';

return [{
  json: {
    filename: `financas-${monthStr}.md`,
    markdown,
    alertTriggered,
    proactiveSay,
    gesture
  }
}];
